const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.25, -29.9]);
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';

  console.log('Analyzing rainfall in La Serena, Chile for July 2022');

  // 2. Data Acquisition & Check
  const precipitation = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(laSerena);

  const collectionSize = precipitation.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No precipitation data available for the specified period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Sum all daily precipitation
  const totalPrecip = precipitation.sum();

  // 4. Calculation - Get total precipitation at point
  const result = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: laSerena,
    scale: 5566,
    maxPixels: 1e9
  }).get('precipitation');

  const totalRainfall = result.getInfo();

  // 5. Validation & Final Answer
  if (totalRainfall === null || totalRainfall === undefined || isNaN(totalRainfall)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Total rainfall in July 2022: ${totalRainfall.toFixed(2)} mm (${(totalRainfall/10).toFixed(2)} cm)`);

  const thresholdMm = 60; // 6cm = 60mm

  if (totalRainfall >= thresholdMm) {
    console.log(`Rainfall (${totalRainfall.toFixed(2)} mm) >= 60 mm threshold`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Rainfall (${totalRainfall.toFixed(2)} mm) < 60 mm threshold`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
